import{_ as s,O as a,o as i,c as o,a as r,i as n,f as p}from"./chunks/framework.fmIt2z2h.js";const f=JSON.parse('{"title":"D.29　城市、空间、住房、乡村与公共可达","description":"","frontmatter":{"title":"D.29　城市、空间、住房、乡村与公共可达","xkChars":735,"xkLessons":{"D.29":{"title":"D.29　城市、空间、住房、乡村与公共可达","lead":"城市编号、几何范围、居民队列和实际可达是不同对象；片区改善要与原住户、迁出者的结果分别记录。","explanation":["原文定位：第4983—4998行，原站定位/theory/appendix-d/d-29#section-d-29。本题切片及完整用户原稿均在source目录，可逐字回查。","短引文：“地图连通之后，实际可达还取决于时段、容量、费用、准入、辅助需求和替代路径”。形成城市的物资条件、历史路径、现有集聚收益不同，不能把当下收益当完整起源解释。位置、行政管辖、成员资格、功能网络、服务区也不能共用一个边界。[T-main]","逐时点采用共同城市名单只控制当期样本差异，跨所有时点固定名单才得到固定统计队列；即便固定编号队列，几何边界和居民仍可变。固定历史面积与固定当前面积可服务不同指数，必须公开分母，不能只凭固定一项宣布全面可比。[T-main]","具体方法案例：联合国2025年12月WUP方法报告34—35页，以2025城市编号为基准，通过重叠追踪；上海2025边界内2000年的九个中心赋同ID，拉各斯在2050投影中与四中心相连仍保留分号。编号连续是一种追踪安排，不是几何边界恒定断言。[P-WUP]","该报告追踪规则中“不分合”不是现实城市空间绝不分合；2050图是投影而非已发生历史。它旨在改善比较，不能反过来推所有跨期分析无效。本人未复算栅格，不把方法描述冒称独立数据验证。[P-WUP]","网络中心性不直接证明权力福利。设施服务区是有假设的空间表示，须核连续路线、服务时段、身体条件及自主使用。看得见设施、合法进入、可负担连续到达、安全活动和改变管理规则的能力分别观察。[T-main]","日常接触错时使用地方熟悉可支持求助看护，但安全尊重和留得住仍需证据。地方参与可能漏租客未来居民及跨区使用者，不能拿现居民多数意见自动替所有受影响位置发言。[T-main]","住房土地权、建筑权、租住保障、抵押、回迁资格与维护费用不同。Roy2005指定两页批评非正规等同贫穷，并指出合法产权与土地使用违规可以并存。因此住区标签不足判断个人贫困或全部法律状态，作者关于分类权力的分析也不授权具体处分。[T-main][P-ROY]","统计目的可合法合并类别，但需保留映射和去重。乡村同时承担生产、非农工作、照护和跨地供给，不是城市的落后阶段；道路可能扩大边缘市场，也可能加强中心企业进入竞争，结果不能预先只留正面或负面。[T-main]","相对增长慢不等绝对衰退。原文更新街区均值提高而居民换批的例子，同样要求保留当前片区真实变化，却不能拿它代替原住户或迁出者生活结果；不否定片区指标，只限制解释对象。[T-main]","灾后须分别追建筑安全再暴露、家庭服务、关系网络、记忆及可行选择救济。迁居不是必坏，原地重建不是必好；可见半恢复不自动证明反馈陷阱，需进一步查循环机制而不是凭外观下结论。[T-main]","连接§5.5.1—5.5.3核聚合边界表述，第十部分核关系圈层，§15.3.7—15.3.8核实际环境承接。新增辨识任务是同一标签背后的对象是否改变、改善是否到原人、路径是否真正可用。[T-main]","八入口为29.01城市形成集聚的不同时间问题；29.02Lefebvre/Harvey空间生产与权利；29.03Jacobs地方知识多样性；29.04住房土地地租及分异；29.05乡村土地制度城乡多功能；29.06区域中心边缘交通竞争；29.07公共空间无障碍日常安全；29.08灾后拆迁重建与记忆。这里解释研究入口，不声称完整复核所有作者原作。[T-main]"],"argumentSteps":["定义行政几何编号居民与服务区各边界。","明确固定名单和面积分母及时间跨度。","测连续可达而不只地图连通。","分土地建筑租住回迁维护的不同权利。","同时追片区、原居民、迁出者及再暴露和救济。"],"distinctions":[{"leftTitle":"固定编号队列","leftText":"同一组ID被追踪。","rightTitle":"固定几何居民","rightText":"范围和人仍可能改变。"},{"leftTitle":"片区均值提高","leftText":"当期区域的统计变化。","rightTitle":"原住户改善","rightText":"需跟踪原人及迁出者。"},{"leftTitle":"非正规标签","leftText":"分类和过程描述。","rightTitle":"具体合法性","rightText":"各项权利行为依规则另核。"},{"leftTitle":"相对增长慢","leftText":"与其他位置相比增速低。","rightTitle":"绝对衰退","rightText":"自身量下降，是另一个命题。"}],"boundaries":["原文教学反例：更新后均值提高，却换了一批居民。","原文边界：半恢复可见组合不自动证明反馈陷阱。","教学反例：固定城市ID但面积扩展，密度分母改变。"],"questions":["同编号就边界不变吗？","标签能授权拆除吗？","均值提高原住户就改善吗？","道路连通足够到达吗？"],"diagramPath":"/reading-assets/S-D-29/figures/d29-boundary.png","caseLinks":[{"title":"WUP2025城市编号的跨期追踪安排","href":"https://population.un.org/wup/assets/Publications/undesa_pd_2025_wup2025_methodological_report.pdf"}],"caseNotes":[{"title":"WUP2025城市编号的跨期追踪安排","text":"报告34—35页说明上海过去九中心赋同ID、拉各斯2050投影相连中心仍分号，保持追踪关系。","sourceLabel":"UN DESA: World Urbanization Prospects 2025 Methodology","sourceUrl":"https://population.un.org/wup/assets/Publications/undesa_pd_2025_wup2025_methodological_report.pdf","sourceLocator":"印刷34—35页（PDF44—45页），MTUC条目及Shanghai/Lagos例","boundary":"方法不是几何恒定保证，2050是投影；未复算栅格或全报告。","href":"https://population.un.org/wup/assets/Publications/undesa_pd_2025_wup2025_methodological_report.pdf"}],"sourceRefs":[{"section":"D.29","start_line":4983,"end_line":4998,"startLine":4983,"endLine":4998}],"outputId":"section-d-29","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","teachingExamples":[{"title":"教学构造：换人提高均值","text":"虚构原片区两住户收入10与20，均值15；之后两户均迁出，新两户30与40，现均值35。现片区均值真实增加20，但原两户迁出后的收入仍未知。","assumptions":"人工完全换人，口径一致，无因果解释。","boundary":"不推所有更新都是替代或迁居必坏。"},{"title":"教学构造：相对落后仍绝对增长","text":"人工边缘产出100到110，中心100到130。边缘增长10%，中心30%，边缘相对慢却绝对增加10。若以中心为分母，比值从1变11/13，但不能写边缘绝对萎缩。","assumptions":"虚构同单位产出，不是福利或净效益。","boundary":"不证明道路造成这些变化。"}],"counterexamples":[{"identity":"constructed_boundary","text":"原文教学反例：更新后均值提高，却换了一批居民。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"source_counterexample","text":"原文边界：半恢复可见组合不自动证明反馈陷阱。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"constructed_boundary","text":"教学反例：固定城市ID但面积扩展，密度分母改变。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]}],"questionAnswers":[{"question":"同编号就边界不变吗？","answer":"不，须看追踪和空间规则。","basis":"真实方法案例。"},{"question":"标签能授权拆除吗？","answer":"不能，具体权利程序另核。","basis":"权限。"},{"question":"均值提高原住户就改善吗？","answer":"不能，人可能变了，须追原人。","basis":"队列。"},{"question":"道路连通足够到达吗？","answer":"还需时间容量费用准入和辅助条件。","basis":"可达。"}],"figures":[{"path":"/reading-assets/S-D-29/figures/d29-boundary.png","alt":"固定ID不固定几何居民，UN追踪分号规则不同。","caption":"WUP2025方法限定。"},{"path":"/reading-assets/S-D-29/figures/d29-residents.png","alt":"人工原均值15现35，原人后续未知。","caption":"教学构造。"},{"path":"/reading-assets/S-D-29/figures/d29-access.png","alt":"可见连通到自主安全使用需要具体路径条件。","caption":"据D.29。"}],"diagramBrief":"三图分城市追踪、居民构成与实际可达。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"本单元涉及方法判断，真实来源仅支持所列事实；图与教学构造分别保留其身份。"},"openQuestions":["未核实际住户迁出后结果或城市数据栅格。","Roy所引经验研究未逐项复核，不据此判具体处分资格。"],"taskId":"S-D-29","sources":[{"id":"T-main","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§D.29，第4983—4998行","claim_support":["空间多边界、可达、住房权利、乡村、更新灾后及八入口。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"P-WUP","title":"UN DESA: World Urbanization Prospects 2025 Methodology","url":"https://population.un.org/wup/assets/Publications/undesa_pd_2025_wup2025_methodological_report.pdf","source_type":"primary","version_or_date":"2025-12方法报告","locator":"印刷34—35页（PDF44—45页），MTUC条目及Shanghai/Lagos例","claim_support":["以2025编号追踪，上海过去九中心赋同ID，拉各斯2050模型连接的中心保持分号，编号不等几何边界固定。"],"limits":["本人直接读指定两页MTUC正文，不声称通读60页或复算栅格；2050是投影情景，不是已发生事实。"],"access_status":"partially_read"},{"id":"P-ROY","title":"Ananya Roy: Urban Informality: Toward an Epistemology of Planning","url":"https://www.wiego.org/wp-content/uploads/2019/09/Urban-Informality-Roy.pdf","source_type":"primary","version_or_date":"2005，JAPA71(2)","locator":"2005，印刷148—149页（PDF2—3页）","claim_support":["原文批评非正规等同贫穷，说明合法产权与违反土地使用规则可以并存及国家分类权力。"],"limits":["本人完整读指定两页，未核全文引用的每个经验研究；为作者理论论述，不是某住户权利判决，更不产生驱逐处分权限。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-D-29/lecture.md","sourcesPath":"/reading-assets/S-D-29/sources.json","sourceSlicePath":"/reading-assets/S-D-29/source/S-D-29.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-D-29/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-d/d-29.md","filePath":"theory/appendix-d/d-29.md"}'),d={name:"theory/appendix-d/d-29.md"};function l(c,e,u,_,m,g){const t=a("SectionLesson");return i(),o("div",null,[e[0]||(e[0]=r('<div class="theory-source"><h1 id="section-d-29" tabindex="-1"><span class="xk-num"><span class="xk-num__n">D.29</span><span class="xk-num__gap">　</span></span>城市、空间、住房、乡村与公共可达 <a class="header-anchor" href="#section-d-29" aria-label="Permalink to &quot;D.29　城市、空间、住房、乡村与公共可达 {#section-d-29}&quot;">​</a></h1><p>正文连接：§5.5.1—5.5.3；§10；§15.3.7—15.3.8。研究入口：29.01—29.08。</p><p>城市形成的物资条件、历史路径和现有集聚收益不同。地理位置、行政管辖、成员资格、功能网络和服务区也不是同一边界。跨期沿用同一城市编号，也须核对统计范围和追踪规则，不能据编号不变认定空间边界固定（联合国人口司，2025）。地图连通之后，实际可达还取决于时段、容量、费用、准入、辅助需求和替代路径；中心性不直接证明权力或福利。</p><p>日常接触、错时使用与地方熟悉可以支持求助和看护，但安全、基本尊重和使用者留得住仍需证据。地方参与也可能排除租客、未来居民和跨区使用者。空间可见、合法使用、可负担的连续到达、安全自主活动及改变管理规则的能力，应分别观察。</p><p>住房的土地权、建筑权、租住保障、抵押、回迁资格和维护费用分开。住区名称和外观不能单独认定个人贫困、违法或处置资格（参见Roy，2005）；为特定统计用途合并类别时，保留分类映射与去重。乡村同时承担生产、非农工作、照护和跨地供给，不是城市的落后阶段。新的道路可以扩大边缘市场，也可加强中心企业进入后的竞争；相对增长较慢不等绝对衰退。</p><p>教学例：更新后的街区平均收入提高，却换了一批居民。当前片区的变化可以成立，不能替代原住户及迁出者的生活结果。灾后应分别追踪建筑安全与再暴露、家庭服务、关系网络、地方记忆及可行选择和救济；迁居并非必坏，原地重建也非必好。半恢复的可见组合不自动证明反馈陷阱。</p><p>逐时点采用共同城市名单，只解决当期样本差异；跨所有时点固定名单才形成固定统计队列，固定队列又不保证几何边界或居民不变。固定历史面积与固定当前面积可以服务不同的合法指数，应把分母写明。设施服务区只是有假设的空间表示，连续路线、实际时段、身体条件和自主使用仍须相应材料。</p><p>专题定位：29.01 城市形成与集聚；29.02 空间生产与城市权利：Lefebvre、Harvey；29.03 地方知识与城市多样性：Jacobs 等；29.04 住房、土地、地租与分异；29.05 乡村社会、土地制度与城乡关系；29.06 区域发展、中心边缘与交通网络；29.07 公共空间、无障碍与日常安全；29.08 灾后重建、拆迁与地方记忆。</p></div>',1)),n(t,{section:"D.29"}),e[1]||(e[1]=p("div",{class:"theory-source"},null,-1))])}const b=s(d,[["render",l]]);export{f as __pageData,b as default};
